#!/usr/bin/env bash
set -euo pipefail

# --- Source Scripts --- #
(return 0 2>/dev/null) && sourced=true || sourced=false
if ! "${sourced}"; then
  source "$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)/helpers.sh"
fi

# --- Read Assets --- #
log INFO "Generating $WEB_HPP..." &
log TRACE "Reading in web assets..." &
INDEX_HTML=$(cat Embedded/web/index.html)
STYLE_CSS=$(cat Embedded/web/style.css)
SCRIPT_JS=$(cat Embedded/web/script.js)

# --- Generate C++ Source --- #
log TRACE "Creating $WEB_HPP file..." &
touch $WEB_HPP
cat <<EOF >"$WEB_HPP"
// Autogenerated file, do not edit!
#pragma once

#include <string_view>

inline constexpr std::string_view INDEX_HTML = R"rawliteral(
$INDEX_HTML
)rawliteral";

inline constexpr std::string_view STYLE_CSS = R"rawliteral(
$STYLE_CSS
)rawliteral";

inline constexpr std::string_view SCRIPT_JS = R"rawliteral(
$SCRIPT_JS
)rawliteral";
EOF
log DEBUG "Generated $WEB_HPP" &
